var quizAutosaveTimer = null;
var quizCountdownTimer = null;
var activeQuizAttempt = null;
var POST_DRAFT_PREFIX = 'lms_post_draft_v20_1_';

function postDraftKey(){ return POST_DRAFT_PREFIX+String(state.user?.username||state.user?.id||'anonymous'); }
function readPostDraft(){
  try{
    const draft=JSON.parse(sessionStorage.getItem(postDraftKey())||'null');
    if(!draft||Date.now()-Number(draft.saved_at||0)>7*86400000){sessionStorage.removeItem(postDraftKey());return null;}
    return draft;
  }catch(_){return null;}
}
function savePostDraft(payload){try{sessionStorage.setItem(postDraftKey(),JSON.stringify({...payload,saved_at:Date.now()}));}catch(_){} }
function clearPostDraft(){try{sessionStorage.removeItem(postDraftKey());}catch(_){} }

function pageStill(name){ return state.page === name && state.user; }
function statusLabel(value){
  return ({draft:'Draf',published:'Terbit',archived:'Diarsipkan',closed:'Ditutup',in_progress:'Sedang dikerjakan',awaiting_review:'Menunggu penilaian esai',graded:'Sudah dinilai',approved:'Disetujui',pending_admin:'Menunggu admin',awaiting_code:'Menunggu kode',rejected:'Ditolak',delivery_failed:'Pengiriman gagal',not_set:'Belum diatur'})[value] || value || '—';
}
function statusClass(value){ return ['published','graded','approved'].includes(value)?'green':['archived','closed','rejected','delivery_failed'].includes(value)?'red':['draft','in_progress','awaiting_review','pending_admin','awaiting_code'].includes(value)?'orange':'gray'; }
function learningPairs(){
  if(state.user.role==='teacher') return state.data.teaching.map(x=>({class_id:x.class_id,subject_id:x.subject_id,class_name:x.class_name,subject_name:x.subject_name}));
  if(state.user.role==='student'){
    const student=state.data.students[0];
    return state.data.subjects.map(x=>({class_id:student.class_id,subject_id:x.id,class_name:student.class_name,subject_name:x.name}));
  }
  const pairs=[];state.data.classes.forEach(c=>state.data.subjects.forEach(s=>pairs.push({class_id:c.id,subject_id:s.id,class_name:c.name,subject_name:s.name})));return pairs;
}
function pairOptions(selectedClass='',selectedSubject=''){
  return learningPairs().map(x=>`<option value="${x.class_id}|${x.subject_id}" ${String(x.class_id)===String(selectedClass)&&String(x.subject_id)===String(selectedSubject)?'selected':''}>${esc(x.class_name)} · ${esc(x.subject_name)}</option>`).join('');
}
function safeLink(value){ return /^https?:\/\//i.test(String(value||''))?String(value):'#'; }
function fileFromBase64(out, fallback){
  const binary=atob(out.file_base64||''),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
  downloadBlob(new Blob([bytes],{type:out.mime_type||'application/octet-stream'}),out.filename||fallback||'berkas');
}
var UI_FILE_LIMIT = 8*1024*1024;
function readUiFile(file){
  return new Promise((resolve,reject)=>{if(!file)return resolve({});if(file.size>UI_FILE_LIMIT)return reject(new Error(`Ukuran ${formatBytes(file.size)} melebihi batas 8 MB.`));const reader=new FileReader();reader.onload=()=>resolve({file_name:file.name,file_type:file.type||'application/octet-stream',file_content:reader.result});reader.onerror=()=>reject(new Error('Berkas gagal dibaca.'));reader.readAsDataURL(file);});
}
function setPostStatus(message,kind='warn'){
  const box=$('#postStatus');if(!box)return;
  box.textContent=message||'';box.className=`result-box ${kind} full${message?'':' hidden'}`;
}
function showAsyncError(page,error){ if(pageStill(page)) $('#pageContent').innerHTML=`${head(titleByPage[page]||'LMS','Data belum dapat dimuat.')}<div class="result-box warn"><b>Terjadi kendala.</b><br>${esc(error.message)}</div>`; }

async function renderTimeline(){
  setLoading();
  try{
    const selected=state.filters.feedClass||'';const out=await api('/api/feed/list'+(selected?`?class_id=${encodeURIComponent(selected)}`:''));if(!pageStill('timeline'))return;
    state.feedData=out;
    const classes=state.user.role==='student'?[{id:state.data.students[0].class_id,name:state.data.students[0].class_name}]:[...new Map(learningPairs().map(x=>[x.class_id,{id:x.class_id,name:x.class_name}])).values()];
    const postButton=`<button class="btn btn-primary" data-action="new-post">＋ ${state.user.role==='student'?'Mulai Diskusi':'Buat Kiriman'}</button>`;
    const cards=out.posts.length?out.posts.map(post=>timelinePost(post,out.comments.filter(c=>Number(c.post_id)===Number(post.id)))).join(''):empty('◉','Linimasa masih kosong','Pengumuman, materi, tugas, kuis, dan diskusi kelas akan muncul di sini.');
    $('#pageContent').innerHTML=`${head('Linimasa Kelas','Ruang komunikasi kelas yang menyatukan pengumuman, materi, tugas, kuis, dan diskusi.',postButton)}
      <div class="toolbar learning-toolbar"><select id="feedClassFilter" class="filter-select"><option value="">Semua kelas yang dapat diakses</option>${classes.map(c=>`<option value="${c.id}" ${String(c.id)===String(selected)?'selected':''}>${esc(c.name)}</option>`).join('')}</select><span class="badge purple">${out.posts.length} kiriman</span><span class="badge green">Email hanya untuk informasi penting</span></div>
      <section class="timeline-layout"><div class="timeline-stream">${cards}</div><aside class="timeline-guide"><article class="panel"><div class="panel-body"><span class="eyebrow">Etika ruang kelas</span><h3>Belajar dan berdiskusi dengan aman</h3><p>Gunakan bahasa santun, bahas materi pembelajaran, dan jangan membagikan data pribadi. Guru dapat mengunci, menutup, atau menghapus konten.</p></div></article><article class="panel"><div class="panel-body"><span class="eyebrow">Penanda</span><div class="legend-list"><span><i class="purple"></i>Diskusi</span><span><i class="orange"></i>Pengumuman penting</span><span><i class="green"></i>Materi / tugas / kuis</span></div></div></article></aside></section>`;
  }catch(error){showAsyncError('timeline',error)}
}
function timelinePost(post,comments){
  const type=post.post_type||'discussion',typeName={discussion:'Diskusi',announcement:'Pengumuman',material:'Materi',assignment:'Tugas',quiz:'Kuis'}[type]||type;
  const manage=post.can_manage?`<div class="post-tools"><button class="text-btn" data-action="edit-post" data-id="${post.id}" ${post.reference_type?'disabled title="Ubah dari sumber asal"':''}>Edit</button><button class="text-btn" data-action="moderate-post" data-operation="${Number(post.is_pinned)?'unpin':'pin'}" data-id="${post.id}">${Number(post.is_pinned)?'Lepas pin':'Pin'}</button><button class="text-btn" data-action="moderate-post" data-operation="${Number(post.comments_locked)?'unlock':'lock'}" data-id="${post.id}">${Number(post.comments_locked)?'Buka komentar':'Kunci'}</button><button class="text-btn" data-action="moderate-post" data-operation="${post.status==='closed'?'reopen':'close'}" data-id="${post.id}">${post.status==='closed'?'Buka kembali':'Tutup'}</button><button class="text-btn danger-text" data-action="moderate-post" data-operation="delete" data-id="${post.id}">Hapus</button></div>`:'';
  const commentHtml=comments.map(c=>`<div class="timeline-comment"><div class="avatar">${initials(c.author_name)}</div><div><b>${esc(c.author_name)}</b><p>${esc(c.body)}</p><small>${fmtDate(c.created_at,true)}</small></div>${c.can_delete?`<div class="comment-tools"><button data-action="edit-comment" data-id="${c.id}" data-post="${post.id}">Edit</button><button data-action="delete-comment" data-id="${c.id}">Hapus</button></div>`:''}</div>`).join('');
  const link=post.reference_type?`<button class="btn btn-sm btn-soft" data-action="open-reference" data-type="${esc(post.reference_type)}" data-ref="${post.reference_id}">Buka ${typeName} →</button>`:'';
  return `<article class="timeline-post ${Number(post.is_pinned)?'pinned':''}"><header><div class="avatar ${type==='announcement'?'avatar-purple':''}">${initials(post.author_name)}</div><div><b>${esc(post.author_name)}</b><span>${esc(post.class_name)} · ${esc(post.subject_name)} · ${fmtDate(post.created_at,true)}</span></div><div class="post-flags">${Number(post.is_pinned)?'<span class="badge purple">Disematkan</span>':''}${Number(post.is_important)?'<span class="badge orange">Penting</span>':''}<span class="badge ${type==='discussion'?'purple':'green'}">${esc(typeName)}</span></div></header><div class="post-copy">${post.title?`<h3>${esc(post.title)}</h3>`:''}<p>${esc(post.body)}</p></div>${post.attachment_name?`<button class="post-attachment" data-action="download-post-file" data-id="${post.id}"><span>📎</span><div><b>${esc(post.attachment_name)}</b><small>${formatBytes(post.attachment_size)} · Privat</small></div><em>Unduh</em></button>`:''}<div class="post-actions">${link}${manage}</div><section class="comment-section">${commentHtml}${!Number(post.comments_locked)&&post.status!=='closed'?`<form class="comment-form" data-post="${post.id}"><div class="avatar">${initials(state.user.full_name)}</div><input class="form-control" name="body" maxlength="3000" placeholder="Tulis komentar yang membangun..." required><button class="btn btn-sm btn-primary">Kirim</button></form>`:'<span class="comments-closed">Komentar ditutup oleh pengelola.</span>'}</section></article>`;
}
function modalPost(id=0){
  const existing=id&&state.feedData?.posts.find(x=>Number(x.id)===id),student=state.user.role==='student';if(id&&!existing)return;
  const draft=!existing&&readPostDraft(),model=existing||draft||{};
  openModal(existing?'Edit Kiriman':(student?'Mulai Diskusi':'Buat Kiriman Kelas'),`<form id="postForm" class="form-grid" novalidate>
    ${draft?'<div class="result-box warn full"><b>Draf sebelumnya dipulihkan.</b><br>Periksa kembali isinya. Jika sebelumnya memilih lampiran, pilih ulang berkas tersebut sebelum menerbitkan.</div>':''}
    <input type="hidden" name="id" value="${existing?.id||''}">
    <label class="full">Kelas & mata pelajaran<select id="postPair" class="form-control" required><option value="">Pilih ruang kelas</option>${pairOptions(model.class_id,model.subject_id)}</select></label>
    ${student?'<input type="hidden" name="post_type" value="discussion">':`<label>Jenis kiriman<select class="form-control" name="post_type"><option value="announcement" ${model.post_type!=='discussion'?'selected':''}>Pengumuman</option><option value="discussion" ${model.post_type==='discussion'?'selected':''}>Diskusi</option></select></label><label>Jadwal terbit <small>(opsional)</small><input class="form-control" type="datetime-local" name="publish_at" value="${esc((model.publish_at||'').slice(0,16))}"></label>`}
    <label class="full">Judul <small>(opsional untuk diskusi)</small><input class="form-control" name="title" maxlength="180" value="${esc(model.title||'')}" placeholder="Topik singkat"></label>
    <label class="full">Isi kiriman<textarea class="form-control tall" name="body" maxlength="10000" required placeholder="Tulis pengumuman atau pertanyaan diskusi...">${esc(model.body||'')}</textarea></label>
    <label class="full">Lampiran privat <small>(opsional, maks. 8 MB)</small><input class="form-control" id="postFile" type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.jpg,.jpeg,.png,.webp,.txt,.zip,.mp3,.mp4"></label>
    ${!student?`<label class="check-line full"><input type="checkbox" name="is_important" value="1" ${model.is_important?'checked':''}><span><b>Kirim sebagai informasi penting</b><small>Membuat notifikasi dalam aplikasi dan antrean email hanya untuk email siswa yang telah disetujui admin.</small></span></label>`:''}
    <div id="postStatus" class="result-box warn full hidden" role="status" aria-live="polite"></div>
    <div class="form-actions full"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button type="submit" class="btn btn-primary">${existing?'Simpan Perubahan':'Terbitkan'}</button></div>
  </form>`,'Linimasa kelas');
}

async function renderNotifications(){
  setLoading();
  try{const out=await api('/api/notifications/list');if(!pageStill('notifications'))return;state.data.notifications=out.notifications;state.data.unread_notifications=out.unread;renderChrome();const rows=out.notifications.length?out.notifications.map(n=>`<article class="notification-row ${n.read_at?'':'unread'}"><div class="notification-kind">${({announcement:'!',assignment:'T',quiz:'?',material:'M',comment:'↩',email_approval:'✉',email_decision:'✉',quiz_result:'☆',deadline_changed:'◷',quiz_cancelled:'×'})[n.kind]||'•'}</div><div><b>${esc(n.title)}</b><p>${esc(n.message)}</p><span>${fmtDate(n.created_at,true)} · ${n.read_at?'Sudah dibaca':'Belum dibaca'}</span></div><button class="btn btn-sm btn-soft" data-action="read-notification" data-id="${n.id}" data-ref-type="${esc(n.reference_type)}" data-ref="${n.reference_id}">${n.read_at?'Buka':'Tandai & buka'}</button></article>`).join(''):empty('♢','Belum ada notifikasi','Aktivitas penting kelas akan muncul di sini.');$('#pageContent').innerHTML=`${head('Notifikasi','Pembaruan kelas, tenggat, hasil kuis, dan status verifikasi email.',out.unread?'<button class="btn btn-secondary" data-action="read-all-notifications">✓ Tandai Semua Dibaca</button>':'')}<section class="notification-list">${rows}</section>`;}catch(error){showAsyncError('notifications',error)}
}

async function renderMaterials(){
  setLoading();
  try{const out=await api('/api/modules/list');if(!pageStill('materials'))return;state.moduleData=out;const teacher=state.user.role==='teacher';const groups=out.modules.length?out.modules.map(module=>{const items=out.materials.filter(x=>Number(x.module_id)===Number(module.id));return `<article class="module-card"><header><div><span class="eyebrow">${esc(module.class_name)} · ${esc(module.subject_name)}</span><h3>${esc(module.position)}. ${esc(module.title)}</h3><p>${esc(module.description||'')}</p></div><span class="badge ${statusClass(module.status)}">${statusLabel(module.status)}</span></header><div class="material-list">${items.length?items.map(material=>materialRow(material,teacher)).join(''):'<p class="muted">Belum ada materi pada modul ini.</p>'}</div>${teacher?`<footer><button class="btn btn-sm btn-soft" data-action="edit-module" data-id="${module.id}">Edit Modul</button><button class="btn btn-sm btn-primary" data-action="add-material" data-id="${module.id}">＋ Tambah Materi</button></footer>`:''}</article>`}).join(''):empty('▥','Belum ada modul','Guru dapat menyusun bab dan materi secara berurutan.');$('#pageContent').innerHTML=`${head('Modul & Materi','Susunan belajar per mata pelajaran: modul atau bab, lalu artikel, tautan, dan berkas privat.',teacher?'<button class="btn btn-primary" data-action="add-module">＋ Buat Modul</button>':'')}<section class="module-grid">${groups}</section>`;}catch(error){showAsyncError('materials',error)}
}
function materialRow(material,teacher){const icon={article:'▤',link:'↗',file:'↓'}[material.material_type]||'•';let action='';if(material.material_type==='link')action=`<a class="btn btn-sm btn-soft" href="${esc(safeLink(material.source_url))}" target="_blank" rel="noopener">Buka Tautan</a>`;if(material.material_type==='file')action=`<button class="btn btn-sm btn-soft" data-action="download-material" data-id="${material.id}">Unduh</button>`;return `<div class="material-row"><span class="material-icon">${icon}</span><div><b>${esc(material.position)}. ${esc(material.title)}</b><p>${esc(material.content||'')}</p><small>${material.publish_at?'Terjadwal '+fmtDate(material.publish_at,true):statusLabel(material.status)}${material.file_name?' · '+esc(material.file_name)+' · '+formatBytes(material.file_size):''}</small></div><div>${action}${teacher?`<button class="btn btn-sm btn-secondary" data-action="edit-material" data-id="${material.id}">Edit</button>`:''}</div></div>`;}
function modalModule(id=0){const m=id&&state.moduleData?.modules.find(x=>Number(x.id)===id);openModal(m?'Edit Modul':'Buat Modul / Bab',`<form id="moduleForm" class="form-grid"><input type="hidden" name="id" value="${m?.id||''}"><label class="full">Kelas & mata pelajaran<select id="modulePair" class="form-control" required><option value="">Pilih penugasan</option>${pairOptions(m?.class_id,m?.subject_id)}</select></label><label class="full">Judul modul / bab<input class="form-control" name="title" value="${esc(m?.title||'')}" maxlength="180" required></label><label>Urutan<input class="form-control" type="number" name="position" min="1" value="${m?.position||1}" required></label><label>Status<select class="form-control" name="status"><option value="draft" ${m?.status==='draft'?'selected':''}>Draf</option><option value="published" ${m?.status==='published'?'selected':''}>Terbit</option><option value="archived" ${m?.status==='archived'?'selected':''}>Arsip</option></select></label><label class="full">Deskripsi<textarea class="form-control" name="description" maxlength="5000">${esc(m?.description||'')}</textarea></label><div class="form-actions full"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button class="btn btn-primary">Simpan Modul</button></div></form>`,'Struktur pembelajaran');}
function modalMaterial(moduleId,id=0){const m=state.moduleData.modules.find(x=>Number(x.id)===Number(moduleId)),item=id&&state.moduleData.materials.find(x=>Number(x.id)===id);if(!m)return;openModal(item?'Edit Materi':'Tambah Materi',`<div class="modal-context"><b>${esc(m.title)}</b><span>${esc(m.class_name)} · ${esc(m.subject_name)}</span></div><form id="materialForm" class="form-grid"><input type="hidden" name="id" value="${item?.id||''}"><input type="hidden" name="module_id" value="${m.id}"><label class="full">Judul materi<input class="form-control" name="title" value="${esc(item?.title||'')}" maxlength="180" required></label><label>Jenis<select class="form-control" name="material_type"><option value="article" ${item?.material_type==='article'?'selected':''}>Artikel</option><option value="link" ${item?.material_type==='link'?'selected':''}>Tautan</option><option value="file" ${item?.material_type==='file'?'selected':''}>Berkas privat</option></select></label><label>Urutan<input class="form-control" type="number" name="position" min="1" value="${item?.position||1}" required></label><label class="full">Isi / ringkasan<textarea class="form-control tall" name="content" maxlength="20000">${esc(item?.content||'')}</textarea></label><label class="full">Tautan sumber <small>(untuk jenis tautan)</small><input class="form-control" type="url" name="source_url" value="${esc(item?.source_url||'')}" placeholder="https://..."></label><label class="full">Berkas <small>${item?.file_name?'Saat ini: '+esc(item.file_name):'maks. 8 MB'}</small><input id="materialFile" class="form-control" type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.jpg,.jpeg,.png,.webp,.txt,.zip,.mp3,.mp4"></label><label>Status<select class="form-control" name="status"><option value="draft" ${item?.status==='draft'?'selected':''}>Draf</option><option value="published" ${item?.status==='published'?'selected':''}>Terbit</option><option value="archived" ${item?.status==='archived'?'selected':''}>Arsip</option></select></label><label>Jadwal terbit <small>(opsional)</small><input class="form-control" type="datetime-local" name="publish_at" value="${esc((item?.publish_at||'').slice(0,16))}"></label><div class="form-actions full"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button class="btn btn-primary">Simpan Materi</button></div></form>`,'Konten pembelajaran');}

async function renderQuizzes(){
  clearQuizTimers();setLoading();
  try{const out=await api('/api/quizzes/list');if(!pageStill('quizzes'))return;state.quizData=out;const teacher=state.user.role==='teacher',admin=state.user.role==='admin';const cards=out.quizzes.length?out.quizzes.map(q=>quizCard(q,teacher,admin)).join(''):empty('?','Belum ada kuis',teacher?'Buat kuis, tambahkan soal, lalu terbitkan untuk siswa.':'Kuis yang diterbitkan guru akan muncul di sini.');$('#pageContent').innerHTML=`${head(teacher?'Kuis':(admin?'Pemantauan Kuis':'Kuis Saya'),teacher?'Buat asesmen objektif dan esai dengan jadwal, durasi, acak soal, kesempatan, dan analisis.':(admin?'Pantau pelaksanaan dan analisis kuis seluruh kelas tanpa mengubah kepemilikan guru.':'Kerjakan kuis sesuai jadwal. Jawaban disimpan berkala selama percobaan aktif.'),teacher?'<button class="btn btn-secondary" data-page="questionBank">☷ Bank Soal</button><button class="btn btn-primary" data-action="add-quiz">＋ Buat Kuis</button>':'')}<section class="quiz-grid">${cards}</section>`;}catch(error){showAsyncError('quizzes',error)}
}
function quizCard(q,teacher,admin=false){
  const now=Date.now(),open=new Date(q.open_at).getTime(),close=new Date(q.close_at).getTime();const windowStatus=now<open?'Belum dibuka':now>close?'Sudah ditutup':'Sedang dibuka';
  if(admin)return `<article class="quiz-card"><header><div class="quiz-mark">?</div><div><span class="eyebrow">${esc(q.class_name)} · ${esc(q.subject_name)}</span><h3>${esc(q.title)}</h3></div><span class="badge ${statusClass(q.status)}">${statusLabel(q.status)}</span></header><p>Pemilik: guru mata pelajaran · ${esc(q.instructions||'Tidak ada petunjuk tambahan.')}</p><div class="quiz-stats"><span><b>${q.question_count}</b> soal</span><span><b>${q.max_score||0}</b> poin</span><span><b>${q.attempt_count}</b> percobaan</span></div><div class="quiz-schedule"><span>Buka ${fmtDate(q.open_at,true)}</span><span>Tutup ${fmtDate(q.close_at,true)}</span></div><footer><button class="btn btn-sm btn-soft" data-action="quiz-attempts" data-id="${q.id}">Lihat Percobaan</button><button class="btn btn-sm btn-soft" data-action="quiz-analysis" data-id="${q.id}">Analisis</button></footer></article>`;
  if(teacher)return `<article class="quiz-card"><header><div class="quiz-mark">?</div><div><span class="eyebrow">${esc(q.class_name)} · ${esc(q.subject_name)}</span><h3>${esc(q.title)}</h3></div><span class="badge ${statusClass(q.status)}">${statusLabel(q.status)}</span></header><p>${esc(q.instructions||'Tidak ada petunjuk tambahan.')}</p><div class="quiz-stats"><span><b>${q.question_count}</b> soal</span><span><b>${q.max_score||0}</b> poin</span><span><b>${q.attempt_count}</b> percobaan</span></div><div class="quiz-schedule"><span>Buka ${fmtDate(q.open_at,true)}</span><span>Tutup ${fmtDate(q.close_at,true)}</span></div><footer><button class="btn btn-sm btn-secondary" data-action="edit-quiz" data-id="${q.id}">Pengaturan</button><button class="btn btn-sm btn-soft" data-action="quiz-questions" data-id="${q.id}">Soal</button><button class="btn btn-sm btn-soft" data-action="quiz-attempts" data-id="${q.id}">Nilai</button><button class="btn btn-sm btn-soft" data-action="quiz-analysis" data-id="${q.id}">Analisis</button><button class="btn btn-sm ${Number(q.show_result)?'btn-secondary':'btn-primary'}" data-action="release-quiz" data-id="${q.id}" data-released="${Number(q.show_result)?'0':'1'}">${Number(q.show_result)?'Sembunyikan Hasil':'Terbitkan Hasil'}</button></footer></article>`;
  const status=q.last_status?`<span class="badge ${statusClass(q.last_status)}">${statusLabel(q.last_status)}</span>`:`<span class="badge ${now>=open&&now<=close?'green':'gray'}">${windowStatus}</span>`;const result=q.released_score!==null&&q.released_score!==undefined;return `<article class="quiz-card student"><header><div class="quiz-mark">?</div><div><span class="eyebrow">${esc(q.subject_name)} · ${esc(q.class_name)}</span><h3>${esc(q.title)}</h3></div>${status}</header><p>${esc(q.instructions||'Baca setiap soal dengan teliti.')}</p><div class="quiz-stats"><span><b>${q.question_count}</b> soal</span><span><b>${q.duration_minutes||'—'}</b> menit</span><span><b>${q.attempt_count}/${q.max_attempts}</b> percobaan</span></div><div class="quiz-schedule"><span>Buka ${fmtDate(q.open_at,true)}</span><span>Tutup ${fmtDate(q.close_at,true)}</span></div><footer>${result?`<button class="btn btn-secondary" data-action="quiz-result" data-id="${q.last_attempt_id}">Lihat Hasil · ${scoreText(q.released_score)}/${scoreText(q.max_score)}</button>`:(q.last_status==='awaiting_review'||q.last_status==='graded'?'<span class="result-box compact">Hasil belum diterbitkan guru.</span>':`<button class="btn btn-primary" data-action="start-quiz" data-id="${q.id}">${q.last_status==='in_progress'?'Lanjutkan':'Mulai Kuis'} →</button>`)}</footer></article>`;
}
function modalQuiz(id=0){const q=id&&state.quizData?.quizzes.find(x=>Number(x.id)===id);const start=new Date(Date.now()+3600000),end=new Date(Date.now()+86400000);const local=v=>{const d=new Date(v),o=d.getTimezoneOffset()*60000;return new Date(d-o).toISOString().slice(0,16)};openModal(q?'Edit Pengaturan Kuis':'Buat Kuis',`<form id="quizForm" class="form-grid"><input type="hidden" name="id" value="${q?.id||''}"><label class="full">Kelas & mata pelajaran<select id="quizPair" class="form-control" required><option value="">Pilih penugasan</option>${pairOptions(q?.class_id,q?.subject_id)}</select></label><label class="full">Judul kuis<input class="form-control" name="title" value="${esc(q?.title||'')}" maxlength="180" required></label><label>Jenis asesmen<select class="form-control" name="assessment_type"><option ${q?.assessment_type==='Formatif'?'selected':''}>Formatif</option><option ${q?.assessment_type==='Sumatif'?'selected':''}>Sumatif</option><option ${q?.assessment_type==='Proyek'?'selected':''}>Proyek</option></select></label><label>Status<select class="form-control" name="status"><option value="draft" ${q?.status==='draft'?'selected':''}>Draf</option><option value="published" ${q?.status==='published'?'selected':''}>Terbit</option><option value="archived" ${q?.status==='archived'?'selected':''}>Arsip</option></select></label><label>Mulai dibuka<input class="form-control" type="datetime-local" name="open_at" value="${local(q?.open_at||start)}" required></label><label>Ditutup<input class="form-control" type="datetime-local" name="close_at" value="${local(q?.close_at||end)}" required></label><label>Durasi menit <small>(0 = sampai ditutup)</small><input class="form-control" type="number" min="0" max="480" name="duration_minutes" value="${q?.duration_minutes||0}" required></label><label>Kesempatan<input class="form-control" type="number" min="1" max="10" name="max_attempts" value="${q?.max_attempts||1}" required></label><label class="full">Tujuan Pembelajaran<input class="form-control" name="tp" value="${esc(q?.tp||'')}" maxlength="3000"></label><label class="full">Petunjuk<textarea class="form-control" name="instructions" maxlength="10000">${esc(q?.instructions||'')}</textarea></label><div class="option-grid full"><label class="check-line"><input type="checkbox" name="shuffle_questions" value="1" ${Number(q?.shuffle_questions)?'checked':''}><span><b>Acak urutan soal</b></span></label><label class="check-line"><input type="checkbox" name="shuffle_options" value="1" ${Number(q?.shuffle_options)?'checked':''}><span><b>Acak opsi jawaban</b></span></label><label class="check-line"><input type="checkbox" name="show_result" value="1" ${Number(q?.show_result)?'checked':''}><span><b>Tampilkan hasil setelah dinilai</b><small>Dapat diubah kemudian dari kartu kuis.</small></span></label></div><div class="form-actions full"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button class="btn btn-primary">Simpan Kuis</button></div></form>`,'Mesin kuis');}

async function openQuizQuestions(id){
  try{const out=await api('/api/quizzes/detail',{method:'POST',body:JSON.stringify({id})});state.quizDetail=out;renderQuizQuestionManager();}catch(error){toast('Gagal',error.message,'error')}
}
function renderQuizQuestionManager(){const out=state.quizDetail,q=out.quiz;openModal(`Soal · ${q.title}`,`<div class="question-manager-head"><div><span class="badge ${statusClass(q.status)}">${statusLabel(q.status)}</span><b>${out.questions.length} soal · ${scoreText(q.max_score)} poin</b></div><div><button class="btn btn-sm btn-secondary" data-action="choose-bank-question" data-id="${q.id}">☷ Ambil dari Bank</button><button class="btn btn-sm btn-primary" data-action="add-quiz-question" data-id="${q.id}">＋ Tulis Soal</button></div></div><div class="question-manager">${out.questions.length?out.questions.map((item,index)=>`<article><span>${index+1}</span><div><b>${esc(item.prompt)}</b><small>${statusLabel(item.question_type)} · ${scoreText(item.points)} poin${item.options?.length?' · '+item.options.map(esc).join(' | '):''}</small></div><button class="text-btn" data-action="edit-quiz-question" data-id="${item.id}">Edit</button><button class="text-btn danger-text" data-action="delete-quiz-question" data-id="${item.id}">Hapus</button></article>`).join(''):empty('?','Belum ada soal','Tambahkan soal sendiri atau ambil dari bank soal.')}</div><div class="form-actions"><button class="btn btn-secondary" data-close-modal>Selesai</button></div>`,'Penyusun kuis');}
function modalQuizQuestion(quizId,id=0){const item=id&&state.quizDetail?.questions.find(x=>Number(x.id)===id);openModal(item?'Edit Soal':'Tulis Soal',`<form id="quizQuestionForm" class="form-grid"><input type="hidden" name="quiz_id" value="${quizId}"><input type="hidden" name="id" value="${item?.id||''}"><label>Jenis soal<select class="form-control" name="question_type"><option value="single" ${item?.question_type==='single'?'selected':''}>Pilihan tunggal</option><option value="multiple" ${item?.question_type==='multiple'?'selected':''}>Pilihan jamak</option><option value="true_false" ${item?.question_type==='true_false'?'selected':''}>Benar / Salah</option><option value="short" ${item?.question_type==='short'?'selected':''}>Jawaban singkat</option><option value="essay" ${item?.question_type==='essay'?'selected':''}>Esai</option></select></label><label>Bobot poin<input class="form-control" type="number" name="points" min="0.1" step="0.1" value="${item?.points||1}" required></label><label class="full">Pertanyaan<textarea class="form-control tall" name="prompt" maxlength="10000" required>${esc(item?.prompt||'')}</textarea></label><label class="full">Pilihan jawaban <small>(satu opsi per baris; tidak digunakan untuk singkat/esai)</small><textarea class="form-control" name="options_text">${esc((item?.options||[]).join('\n'))}</textarea></label><label class="full">Kunci jawaban <small>(satu jawaban per baris; kosong untuk esai)</small><textarea class="form-control" name="correct_text">${esc((item?.correct||[]).join('\n'))}</textarea></label><label>Urutan<input class="form-control" type="number" min="1" name="position" value="${item?.position||((state.quizDetail?.questions.length||0)+1)}"></label><label>Tag bank soal<input class="form-control" name="tags" placeholder="contoh: bilangan, dasar"></label><label class="full">Pembahasan<textarea class="form-control" name="explanation" maxlength="5000">${esc(item?.explanation||'')}</textarea></label>${!item?'<label class="check-line full"><input type="checkbox" name="save_to_bank" value="1"><span><b>Simpan salinan ke bank soal</b><small>Soal dapat digunakan kembali pada kuis lain.</small></span></label>':''}<div class="form-actions full"><button type="button" class="btn btn-secondary" data-action="return-question-manager">Batal</button><button class="btn btn-primary">Simpan Soal</button></div></form>`,'Editor soal');}
async function chooseBankQuestion(quizId){try{const quiz=state.quizDetail.quiz,out=await api(`/api/question-bank/list?subject_id=${quiz.subject_id}`);openModal('Ambil dari Bank Soal',`<div class="question-manager">${out.questions.length?out.questions.map(item=>`<article><span>?</span><div><b>${esc(item.prompt)}</b><small>${statusLabel(item.question_type)} · ${scoreText(item.points)} poin · ${esc(item.tags||'Tanpa tag')}</small></div><button class="btn btn-sm btn-primary" data-action="use-bank-question" data-id="${item.id}" data-quiz="${quizId}" data-points="${item.points}">Tambahkan</button></article>`).join(''):empty('☷','Bank soal kosong','Tambahkan soal ke bank terlebih dahulu.')}</div><div class="form-actions"><button class="btn btn-secondary" data-action="return-question-manager">Kembali</button></div>`,'Bank soal');}catch(error){toast('Gagal',error.message,'error')}}

async function renderQuestionBank(){
  if(state.user.role!=='teacher'){state.page='dashboard';return renderDashboard()}setLoading();
  try{const out=await api('/api/question-bank/list');if(!pageStill('questionBank'))return;state.bankData=out;const rows=out.questions.length?out.questions.map(item=>`<article class="bank-row"><div class="quiz-mark">?</div><div><b>${esc(item.prompt)}</b><p>${statusLabel(item.question_type)} · ${scoreText(item.points)} poin · ${esc(item.tags||'Tanpa tag')}</p></div><button class="btn btn-sm btn-secondary" data-action="edit-bank-question" data-id="${item.id}">Edit</button><button class="btn btn-sm btn-danger" data-action="delete-bank-question" data-id="${item.id}">Hapus</button></article>`).join(''):empty('☷','Bank soal kosong','Simpan soal yang dapat dipakai kembali lintas kuis pada mata pelajaran yang sama.');$('#pageContent').innerHTML=`${head('Bank Soal','Kelola soal objektif dan esai yang dapat digunakan kembali pada kuis lain.','<button class="btn btn-primary" data-action="add-bank-question">＋ Tambah Soal Bank</button>')}<section class="bank-list">${rows}</section>`;}catch(error){showAsyncError('questionBank',error)}
}
function modalBankQuestion(id=0){const item=id&&state.bankData?.questions.find(x=>Number(x.id)===id);const subjects=[...new Map(state.data.teaching.map(x=>[x.subject_id,{id:x.subject_id,name:x.subject_name}])).values()];openModal(item?'Edit Soal Bank':'Tambah Soal Bank',`<form id="bankQuestionForm" class="form-grid"><input type="hidden" name="id" value="${item?.id||''}"><label>Mata pelajaran<select class="form-control" name="subject_id" required>${subjects.map(s=>`<option value="${s.id}" ${Number(item?.subject_id)===Number(s.id)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Jenis<select class="form-control" name="question_type"><option value="single" ${item?.question_type==='single'?'selected':''}>Pilihan tunggal</option><option value="multiple" ${item?.question_type==='multiple'?'selected':''}>Pilihan jamak</option><option value="true_false" ${item?.question_type==='true_false'?'selected':''}>Benar / Salah</option><option value="short" ${item?.question_type==='short'?'selected':''}>Jawaban singkat</option><option value="essay" ${item?.question_type==='essay'?'selected':''}>Esai</option></select></label><label class="full">Pertanyaan<textarea class="form-control tall" name="prompt" required>${esc(item?.prompt||'')}</textarea></label><label class="full">Pilihan <small>(satu per baris)</small><textarea class="form-control" name="options_text">${esc((item?.options||[]).join('\n'))}</textarea></label><label class="full">Kunci <small>(satu per baris, kosong untuk esai)</small><textarea class="form-control" name="correct_text">${esc((item?.correct||[]).join('\n'))}</textarea></label><label>Bobot<input class="form-control" type="number" min="0.1" step="0.1" name="points" value="${item?.points||1}" required></label><label>Tag<input class="form-control" name="tags" value="${esc(item?.tags||'')}"></label><label class="full">Pembahasan<textarea class="form-control" name="explanation">${esc(item?.explanation||'')}</textarea></label><div class="form-actions full"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button class="btn btn-primary">Simpan ke Bank</button></div></form>`,'Bank soal');}
function questionPayload(obj){const lines=value=>String(value||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);return {...obj,subject_id:Number(obj.subject_id||0),quiz_id:Number(obj.quiz_id||0),id:Number(obj.id||0),points:Number(obj.points),position:Number(obj.position||1),options:lines(obj.options_text),correct:lines(obj.correct_text),save_to_bank:Boolean(obj.save_to_bank)};}

async function openStudentQuiz(id){
  try{const out=await api('/api/quizzes/attempt/start',{method:'POST',body:JSON.stringify({quiz_id:id})});activeQuizAttempt=out;renderQuizAttempt(out);startQuizAutosave();}catch(error){toast('Kuis belum dapat dibuka',error.message,'error')}
}
function renderQuizAttempt(out){
  const inputs=out.questions.map((q,index)=>{let field='';if(['single','true_false'].includes(q.question_type))field=`<div class="quiz-options">${q.options.map(opt=>`<label><input type="radio" name="q-${q.id}" value="${esc(opt)}" ${String(q.answer)===String(opt)?'checked':''}><span>${esc(opt)}</span></label>`).join('')}</div>`;else if(q.question_type==='multiple')field=`<div class="quiz-options">${q.options.map(opt=>`<label><input type="checkbox" name="q-${q.id}" value="${esc(opt)}" ${Array.isArray(q.answer)&&q.answer.includes(opt)?'checked':''}><span>${esc(opt)}</span></label>`).join('')}</div>`;else field=`<textarea class="form-control ${q.question_type==='essay'?'tall':''}" name="q-${q.id}" placeholder="Tulis jawaban...">${esc(q.answer||'')}</textarea>`;return `<article class="attempt-question" data-question="${q.id}" data-type="${q.question_type}"><header><span>Soal ${index+1}</span><b>${scoreText(q.points)} poin</b></header><p>${esc(q.prompt)}</p>${field}</article>`;}).join('');
  openModal(out.quiz.title,`<div class="attempt-top"><div><span>Percobaan ${out.quiz.attempt_no} dari ${out.quiz.max_attempts}</span><b id="quizCountdown">Menghitung waktu...</b></div><div id="autosaveStatus">Jawaban akan disimpan otomatis.</div></div><p class="attempt-instructions">${esc(out.quiz.instructions||'Jawab seluruh pertanyaan lalu tekan Kirim Kuis.')}</p><form id="quizAttemptForm"><input type="hidden" name="attempt_id" value="${out.attempt.id}"><div class="attempt-questions">${inputs}</div><div class="attempt-submit"><span id="autosaveStatusBottom">Autosave aktif setiap 20 detik.</span><button type="button" class="btn btn-secondary" data-action="save-quiz-draft">Simpan Sekarang</button><button class="btn btn-primary">Kirim Kuis</button></div></form>`,'Percobaan aktif');
  updateQuizCountdown();quizCountdownTimer=setInterval(updateQuizCountdown,1000);
}
function collectQuizAnswers(){if(!activeQuizAttempt)return[];return activeQuizAttempt.questions.map(q=>{const nodes=$$(`[name="q-${q.id}"]`);let answer='';if(q.question_type==='multiple')answer=nodes.filter(x=>x.checked).map(x=>x.value);else if(['single','true_false'].includes(q.question_type))answer=nodes.find(x=>x.checked)?.value||'';else answer=nodes[0]?.value||'';return {question_id:q.id,answer};});}
async function saveQuizDraft(silent=false){if(!activeQuizAttempt)return;const status=$('#autosaveStatus');try{if(status)status.textContent='Menyimpan jawaban...';await api('/api/quizzes/attempt/save',{method:'POST',body:JSON.stringify({attempt_id:activeQuizAttempt.attempt.id,answers:collectQuizAnswers()})});if(status)status.textContent=`Tersimpan ${new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}`;if(!silent)toast('Jawaban tersimpan','Anda dapat melanjutkan mengerjakan kuis.');}catch(error){if(status)status.textContent='Autosave gagal — simpan kembali.';if(!silent)toast('Gagal menyimpan',error.message,'error')}}
function startQuizAutosave(){clearInterval(quizAutosaveTimer);quizAutosaveTimer=setInterval(()=>saveQuizDraft(true),20000);}
function updateQuizCountdown(){const target=activeQuizAttempt&&new Date(activeQuizAttempt.attempt.expires_at).getTime(),el=$('#quizCountdown');if(!target||!el)return;const left=Math.max(0,target-Date.now()),minutes=Math.floor(left/60000),seconds=Math.floor((left%60000)/1000);el.textContent=`Sisa waktu ${minutes}:${String(seconds).padStart(2,'0')}`;if(left<=0){clearQuizTimers();submitActiveQuiz(true);}}
function clearQuizTimers(){clearInterval(quizAutosaveTimer);clearInterval(quizCountdownTimer);quizAutosaveTimer=quizCountdownTimer=null;}
async function submitActiveQuiz(timedOut=false){if(!activeQuizAttempt)return;const form=$('#quizAttemptForm'),btn=form&&$('button[type="submit"]',form);if(btn){btn.disabled=true;btn.textContent='Mengirim...';}try{await saveQuizDraft(true);const out=await api('/api/quizzes/attempt/submit',{method:'POST',body:JSON.stringify({attempt_id:activeQuizAttempt.attempt.id})});clearQuizTimers();activeQuizAttempt=null;closeModal();toast(timedOut?'Waktu habis':'Kuis terkirim',out.result_released?`Nilai ${scoreText(out.score)} tersedia.`:out.status==='awaiting_review'?'Jawaban esai menunggu penilaian guru.':'Hasil menunggu pengaturan guru.');await loadData();state.page='quizzes';renderQuizzes();}catch(error){toast('Kuis belum terkirim',error.message,'error');if(btn){btn.disabled=false;btn.textContent='Kirim Kuis';}}}
async function openQuizResult(attemptId){try{const out=await api('/api/quizzes/attempt/result',{method:'POST',body:JSON.stringify({attempt_id:attemptId})});const max=out.questions.reduce((sum,q)=>sum+Number(q.points||0),0);openModal(`Hasil · ${out.quiz.title}`,`<section class="result-hero"><span>Nilai Anda</span><b>${scoreText(out.attempt.total_score)} <small>/ ${scoreText(max)}</small></b><p>${esc(out.attempt.feedback||'Hasil kuis telah diterbitkan.')}</p></section><div class="result-question-list">${out.questions.map((q,index)=>`<article><header><b>${index+1}. ${esc(q.prompt)}</b><span>${scoreText((out.answers.find(a=>Number(a.question_id)===Number(q.id))?.auto_score||0)+(out.answers.find(a=>Number(a.question_id)===Number(q.id))?.manual_score||0))}/${scoreText(q.points)}</span></header><p>Jawaban: ${esc(Array.isArray(q.answer)?q.answer.join(', '):q.answer||'—')}</p>${q.correct?.length?`<small>Kunci: ${esc(q.correct.join(', '))}</small>`:''}${q.explanation?`<small>Pembahasan: ${esc(q.explanation)}</small>`:''}</article>`).join('')}</div><div class="form-actions"><button class="btn btn-secondary" data-close-modal>Tutup</button></div>`,'Hasil kuis');}catch(error){toast('Hasil belum tersedia',error.message,'error')}}

async function openQuizAttempts(quizId){try{const out=await api('/api/quizzes/attempts/list',{method:'POST',body:JSON.stringify({quiz_id:quizId})});state.quizAttempts=out;openModal(`Penilaian · ${out.quiz.title}`,`<div class="table-wrap"><table class="data-table"><thead><tr><th>Siswa</th><th>Percobaan</th><th>Status</th><th>Nilai</th><th></th></tr></thead><tbody>${out.attempts.length?out.attempts.map(a=>`<tr><td><b>${esc(a.attendance_no)} · ${esc(a.student_name)}</b><small class="table-subline">${fmtDate(a.submitted_at||a.started_at,true)}</small></td><td>${a.attempt_no}</td><td><span class="badge ${statusClass(a.status)}">${statusLabel(a.status)}</span></td><td>${scoreText(a.total_score)}</td><td>${['awaiting_review','graded'].includes(a.status)?`<button class="btn btn-sm btn-soft" data-action="${state.user.role==='admin'?'view-quiz-attempt':'review-quiz-attempt'}" data-id="${a.id}">${state.user.role==='admin'?'Lihat':(a.status==='graded'?'Lihat / Ubah':'Nilai Esai')}</button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="5">Belum ada percobaan siswa.</td></tr>'}</tbody></table></div><div class="form-actions"><button class="btn btn-secondary" data-close-modal>Tutup</button></div>`,'Percobaan siswa');}catch(error){toast('Gagal',error.message,'error')}}
async function openAttemptReview(attemptId){try{const out=await api('/api/quizzes/attempt/result',{method:'POST',body:JSON.stringify({attempt_id:attemptId})});state.attemptReview=out;const answers=new Map(out.answers.map(a=>[Number(a.question_id),a]));openModal(`Periksa · ${out.quiz.title}`,`<form id="quizGradeForm"><input type="hidden" name="attempt_id" value="${attemptId}"><div class="review-question-list">${out.questions.map((q,index)=>{const ans=answers.get(Number(q.id));return `<article><header><b>${index+1}. ${esc(q.prompt)}</b><span>${scoreText(q.points)} poin</span></header><div class="review-answer"><b>Jawaban siswa</b><p>${esc(Array.isArray(q.answer)?q.answer.join(', '):q.answer||'—')}</p></div>${q.question_type==='essay'?`<div class="essay-grade"><label>Nilai<input class="form-control essay-score" data-question="${q.id}" type="number" min="0" max="${q.points}" step="0.1" value="${ans?.manual_score??''}" required></label><label>Umpan balik<input class="form-control essay-feedback" data-question="${q.id}" value="${esc(ans?.feedback||'')}"></label></div>`:`<span class="badge ${Number(ans?.is_correct)===1?'green':'red'}">${Number(ans?.is_correct)===1?'Benar':'Belum tepat'} · ${scoreText(ans?.auto_score||0)} poin</span>`}</article>`}).join('')}</div><label style="display:grid;gap:7px;margin-top:14px;font-size:11px;font-weight:700">Umpan balik keseluruhan<textarea class="form-control" name="feedback">${esc(out.attempt.feedback||'')}</textarea></label><div class="form-actions"><button type="button" class="btn btn-secondary" data-action="back-to-attempts">Kembali</button><button class="btn btn-primary">Simpan Penilaian</button></div></form>`,'Penilaian kuis');}catch(error){toast('Gagal',error.message,'error')}}
async function openQuizAnalysis(quizId){try{const out=await api('/api/quizzes/analysis',{method:'POST',body:JSON.stringify({quiz_id:quizId})});openModal('Analisis Butir Kuis',`<section class="stat-grid compact-stats">${stat('♙','purple','Percobaan',out.attempts,'Sudah dikirim')}${stat('?','green','Butir',out.items.length,'Dalam kuis')}</section><div class="table-wrap"><table class="data-table"><thead><tr><th>Butir</th><th>Jenis</th><th>Dijawab</th><th>Benar</th><th>Rerata poin</th></tr></thead><tbody>${out.items.map((item,index)=>`<tr><td><b>${index+1}. ${esc(item.prompt)}</b></td><td>${statusLabel(item.type)}</td><td>${item.answered}/${out.attempts}</td><td>${item.type==='essay'?'Manual':item.correct+'/'+out.attempts}</td><td>${scoreText(item.average_score)}/${scoreText(item.points)}</td></tr>`).join('')}</tbody></table></div><div class="form-actions"><button class="btn btn-secondary" data-close-modal>Tutup</button></div>`,'Analisis hasil');}catch(error){toast('Gagal',error.message,'error')}}

function renderProfile(){
  if(state.user.role!=='student'){state.page='dashboard';return renderDashboard()}const u=state.user,s=state.data.students[0],contact=state.data.contact,status=contact?.email_status||'not_set';
  const action=status==='awaiting_code'?`<button class="btn btn-primary" data-action="confirm-email-code">Masukkan Kode</button>`:status==='pending_admin'?'<span class="badge orange">Menunggu pemeriksaan administrator</span>':status==='approved'?'<span class="badge green">✓ Email aktif untuk notifikasi penting & pemulihan</span>':`<button class="btn btn-primary" data-action="request-email">${status==='rejected'||status==='delivery_failed'?'Ajukan Ulang Email':'Tambah Email Aktif'}</button>`;
  $('#pageContent').innerHTML=`${head('Profil & Email','Periksa identitas resmi akun, amankan kata sandi, dan verifikasi email milik sendiri.')}<section class="profile-layout"><article class="profile-card"><div class="profile-avatar">${initials(u.full_name)}</div><h3>${esc(u.full_name)}</h3><p>${esc(s.class_name)} · Nomor absen ${esc(s.attendance_no)}</p><dl><div><dt>Nama pengguna</dt><dd>${esc(u.username)}</dd></div><div><dt>Jenis kelamin</dt><dd>${s.gender==='L'?'Laki-laki':'Perempuan'}</dd></div><div><dt>Tahun pelajaran</dt><dd>${esc(state.data.academic_year)}</dd></div></dl><p class="identity-note">Identitas resmi dikelola administrator dan tidak dapat diubah oleh siswa.</p></article><div><article class="panel"><div class="panel-head"><div><h3>Email siswa</h3><p>Email harus dibuktikan dengan kode, lalu disetujui administrator.</p></div><span class="badge ${statusClass(status)}">${statusLabel(status)}</span></div><div class="panel-body"><div class="email-state"><span>✉</span><div><b>${esc(contact?.email||'Belum ada email')}</b><p>${status==='approved'?'Notifikasi penting dan pemulihan kata sandi telah aktif.':status==='pending_admin'?'Kepemilikan email sudah terbukti. Admin akan memeriksa kesesuaiannya.':status==='awaiting_code'?'Periksa kotak masuk atau spam, lalu masukkan kode 6 digit.':'Gunakan alamat email aktif milik sendiri, bukan milik teman.'}</p></div></div><div class="form-actions">${action}</div></div></article><article class="panel"><div class="panel-head"><div><h3>Keamanan akun</h3><p>Gunakan kata sandi pribadi yang tidak dibagikan kepada siapa pun.</p></div></div><div class="panel-body"><button class="btn btn-secondary" data-action="change-password">🔑 Ganti Kata Sandi</button></div></article></div></section>`;
}
function modalEmailRequest(){openModal('Verifikasi Email Milik Siswa',`<div class="result-box warn"><b>Gunakan email aktif milik Anda sendiri.</b><br>Kode berlaku 15 menit. Setelah kode benar, administrator sekolah masih harus menyetujui email.</div><form id="emailRequestForm" style="margin-top:15px"><label style="display:grid;gap:8px;font-size:12px;font-weight:700">Alamat email<input class="form-control" type="email" name="email" value="${esc(state.data.contact?.email||'')}" required placeholder="nama@email.com"></label><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button class="btn btn-primary">Kirim Kode</button></div></form>`,'Kepemilikan email');}
function modalEmailCode(){openModal('Masukkan Kode Verifikasi',`<form id="emailCodeForm"><p class="muted">Masukkan kode 6 digit yang dikirim ke <b>${esc(state.data.contact?.email||'email Anda')}</b>.</p><input class="form-control verification-code" name="code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" placeholder="000000" required><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button class="btn btn-primary">Verifikasi Kode</button></div></form>`,'Kepemilikan email');}

function renderContacts(){
  if(state.user.role!=='admin'){state.page='dashboard';return renderDashboard()}const contacts=state.data.user_contacts||[],pending=contacts.filter(x=>x.email_status==='pending_admin'),rows=contacts.length?contacts.map(c=>`<tr><td><div class="person"><div class="avatar">${initials(c.full_name)}</div><div><b>${esc(c.full_name)}</b><small>${esc(c.username)}</small></div></div></td><td>${esc(c.email)}</td><td><span class="badge ${statusClass(c.email_status)}">${statusLabel(c.email_status)}</span></td><td>${fmtDate(c.email_verified_at||c.requested_at,true)}</td><td>${c.email_status==='pending_admin'?`<button class="btn btn-sm btn-primary" data-action="email-decision" data-id="${c.id}" data-decision="approve">Setujui</button> <button class="btn btn-sm btn-danger" data-action="email-decision" data-id="${c.id}" data-decision="reject">Tolak</button>`:'—'}</td></tr>`).join(''):'<tr><td colspan="5">Belum ada pengajuan email siswa.</td></tr>';$('#pageContent').innerHTML=`${head('Verifikasi Email Siswa','Periksa email yang kepemilikannya telah dibuktikan siswa. Template impor tetap empat kolom tanpa email.')}<section class="stat-grid">${stat('✉','orange','Menunggu Keputusan',pending.length,'Perlu diperiksa admin')}${stat('✓','green','Disetujui',contacts.filter(x=>x.email_status==='approved').length,'Aktif untuk pemulihan')}${stat('×','red','Ditolak',contacts.filter(x=>x.email_status==='rejected').length,'Dapat diajukan ulang')}${stat('♙','purple','Total Pengajuan',contacts.length,'Semua status')}</section><section class="table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Siswa</th><th>Email</th><th>Status</th><th>Terbukti pada</th><th>Keputusan</th></tr></thead><tbody>${rows}</tbody></table></div></section>`;
}

function modalForgotPassword(){openModal('Pulihkan Kata Sandi',`<div class="recovery-steps"><span class="active">1. Minta kode</span><span>2. Buat sandi baru</span></div><form id="recoveryRequestForm"><label style="display:grid;gap:8px;font-size:12px;font-weight:700">Nama pengguna<input id="recoveryUsername" class="form-control" name="username" autocomplete="username" required></label><p class="form-help">Jika akun memiliki email yang telah disetujui admin, kode 6 digit akan dikirim. Pesan tetap sama bila akun tidak ditemukan untuk melindungi data pengguna.</p><div class="form-actions"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button class="btn btn-primary">Kirim Kode Pemulihan</button></div></form>`,'Pemulihan mandiri');}
function showRecoveryConfirm(username){$('#modalTitle').textContent='Buat Kata Sandi Baru';$('#modalBody').innerHTML=`<div class="recovery-steps"><span>1. Kode diminta</span><span class="active">2. Buat sandi baru</span></div><div class="result-box good">Jika akun dan email terverifikasi ditemukan, kode telah dikirim. Periksa kotak masuk dan folder spam.</div><form id="recoveryConfirmForm" class="form-grid" style="margin-top:15px"><input type="hidden" name="username" value="${esc(username)}"><label class="full">Kode 6 digit<input class="form-control verification-code" name="code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" required></label><label>Kata sandi baru<input class="form-control" type="password" name="new_password" minlength="8" maxlength="128" required></label><label>Ulangi kata sandi<input class="form-control" type="password" name="confirm_password" minlength="8" maxlength="128" required></label><div class="form-actions full"><button type="button" class="btn btn-secondary" data-close-modal>Batal</button><button class="btn btn-primary">Pulihkan Kata Sandi</button></div></form>`;}

function navigateReference(type,id){
  if(type==='quiz'||type==='quiz_attempt'){state.page='quizzes';renderPage();if(type==='quiz_attempt'&&id)setTimeout(()=>openQuizResult(id),50);return}
  if(type==='material'){state.page='materials';renderPage();return}
  if(type==='assignment'){state.page='assignments';renderPage();return}
  if(type==='post'){state.page='timeline';renderPage();return}
  if(type==='user_contact'){state.page=state.user.role==='admin'?'contacts':'profile';renderPage();return}
}

// Extra actions are handled after the core app's delegated listener. Unknown actions
// are intentionally no-ops in app.js, then resolved here.
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action,id=Number(button.dataset.id||0);
  if(action==='forgot-password')return modalForgotPassword();
  if(action==='new-post')return modalPost();
  if(action==='edit-post')return modalPost(id);
  if(action==='edit-comment'){const c=state.feedData?.comments.find(x=>Number(x.id)===id);if(!c)return;const body=prompt('Ubah komentar:',c.body);if(body===null||!body.trim())return;try{await api('/api/feed/comment/save',{method:'POST',body:JSON.stringify({id,post_id:Number(button.dataset.post),body})});toast('Komentar diperbarui');renderTimeline();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(action==='delete-comment'){if(!confirm('Hapus komentar ini?'))return;try{await api('/api/feed/comment/delete',{method:'POST',body:JSON.stringify({comment_id:id})});toast('Komentar dihapus');renderTimeline();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(action==='moderate-post'){const operation=button.dataset.operation;if(operation==='delete'&&!confirm('Hapus kiriman ini dari linimasa?'))return;try{await api('/api/feed/post/moderate',{method:'POST',body:JSON.stringify({post_id:id,operation})});toast('Linimasa diperbarui');renderTimeline();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(action==='download-post-file'){button.disabled=true;try{fileFromBase64(await api('/api/feed/file',{method:'POST',body:JSON.stringify({id})}),'lampiran');}catch(error){toast('Gagal',error.message,'error')}finally{button.disabled=false}return;}
  if(action==='open-reference')return navigateReference(button.dataset.type,Number(button.dataset.ref));
  if(action==='read-notification'){try{if(!state.data.notifications.find(x=>Number(x.id)===id)?.read_at)await api('/api/notifications/read',{method:'POST',body:JSON.stringify({id})});navigateReference(button.dataset.refType,Number(button.dataset.ref));if(state.page==='notifications')renderNotifications();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(action==='read-all-notifications'){try{await api('/api/notifications/read',{method:'POST',body:JSON.stringify({all:true})});await loadData();state.page='notifications';renderNotifications();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(action==='add-module')return modalModule();if(action==='edit-module')return modalModule(id);
  if(action==='add-material')return modalMaterial(id);if(action==='edit-material'){const item=state.moduleData.materials.find(x=>Number(x.id)===id);return modalMaterial(item.module_id,id)}
  if(action==='download-material'){button.disabled=true;try{fileFromBase64(await api('/api/materials/file',{method:'POST',body:JSON.stringify({id})}),'materi');}catch(error){toast('Gagal',error.message,'error')}finally{button.disabled=false}return;}
  if(action==='add-quiz')return modalQuiz();if(action==='edit-quiz')return modalQuiz(id);if(action==='quiz-questions')return openQuizQuestions(id);if(action==='add-quiz-question')return modalQuizQuestion(id);if(action==='edit-quiz-question')return modalQuizQuestion(state.quizDetail.quiz.id,id);if(action==='return-question-manager')return renderQuizQuestionManager();if(action==='choose-bank-question')return chooseBankQuestion(id);
  if(action==='use-bank-question'){try{await api('/api/quizzes/question/save',{method:'POST',body:JSON.stringify({quiz_id:Number(button.dataset.quiz),bank_question_id:id,points:Number(button.dataset.points),position:(state.quizDetail.questions.length||0)+1})});toast('Soal ditambahkan','Salinan bank masuk ke kuis.');await openQuizQuestions(Number(button.dataset.quiz));}catch(error){toast('Gagal',error.message,'error')}return;}
  if(action==='delete-quiz-question'){if(!confirm('Hapus soal ini dari kuis?'))return;try{await api('/api/quizzes/question/delete',{method:'POST',body:JSON.stringify({id})});toast('Soal dihapus');await openQuizQuestions(state.quizDetail.quiz.id);}catch(error){toast('Gagal',error.message,'error')}return;}
  if(action==='quiz-attempts')return openQuizAttempts(id);if(action==='view-quiz-attempt')return openQuizResult(id);if(action==='review-quiz-attempt')return openAttemptReview(id);if(action==='back-to-attempts')return openQuizAttempts(state.quizAttempts.quiz.id);if(action==='quiz-analysis')return openQuizAnalysis(id);
  if(action==='release-quiz'){try{await api('/api/quizzes/results/release',{method:'POST',body:JSON.stringify({quiz_id:id,released:button.dataset.released==='1'})});toast('Pengaturan hasil diperbarui',button.dataset.released==='1'?'Siswa yang sudah dinilai dapat melihat hasil.':'Hasil disembunyikan dari siswa.');renderQuizzes();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(action==='start-quiz')return openStudentQuiz(id);if(action==='quiz-result')return openQuizResult(id);if(action==='save-quiz-draft')return saveQuizDraft();
  if(action==='open-quiz'){const assignment=state.data.assignments.find(x=>Number(x.id)===id);state.page='quizzes';renderPage();if(assignment?.source_id&&!assignment.submission_id)setTimeout(()=>openStudentQuiz(Number(assignment.source_id)),100);return;}
  if(action==='manage-quiz-assignment'){const assignment=state.data.assignments.find(x=>Number(x.id)===id);state.page='quizzes';renderPage();if(assignment?.source_id)setTimeout(()=>openQuizAttempts(Number(assignment.source_id)),100);return;}
  if(action==='add-bank-question')return modalBankQuestion();if(action==='edit-bank-question')return modalBankQuestion(id);if(action==='delete-bank-question'){if(!confirm('Hapus soal ini dari bank? Salinan yang sudah masuk kuis tidak terpengaruh.'))return;try{await api('/api/question-bank/delete',{method:'POST',body:JSON.stringify({id})});toast('Soal bank dihapus');renderQuestionBank();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(action==='request-email')return modalEmailRequest();if(action==='confirm-email-code')return modalEmailCode();
  if(action==='email-decision'){try{await api('/api/admin/email/decision',{method:'POST',body:JSON.stringify({contact_id:id,decision:button.dataset.decision})});toast('Keputusan tersimpan');await loadData();state.page='contacts';renderContacts();}catch(error){toast('Gagal',error.message,'error')}return;}
});

document.addEventListener('change',event=>{
  if(event.target.id==='feedClassFilter'){state.filters.feedClass=event.target.value;renderTimeline();return;}
  if(event.target.id==='postFile'){
    const file=event.target.files?.[0];
    if(!file){setPostStatus('');return;}
    if(file.size>UI_FILE_LIMIT){setPostStatus(`Lampiran ${file.name} berukuran ${formatBytes(file.size)} dan melebihi batas 8 MB. Pilih berkas yang lebih kecil.`);return;}
    setPostStatus(`Lampiran siap: ${file.name} (${formatBytes(file.size)}).`,'good');
  }
});
document.addEventListener('click',event=>{
  const postForm=$('#postForm');
  if(postForm?.dataset.submitting==='1'&&event.target.closest('[data-close-modal]')){event.preventDefault();event.stopImmediatePropagation();setPostStatus('Kiriman sedang diproses. Tunggu sampai berhasil atau muncul pesan kesalahan.');return;}
  if(event.target.closest('[data-close-modal]')&&activeQuizAttempt){saveQuizDraft(true);clearQuizTimers();activeQuizAttempt=null;}
},true);

document.addEventListener('submit',async event=>{
  const form=event.target;
  if(form.matches('.comment-form')){event.preventDefault();const input=$('input[name="body"]',form);try{await api('/api/feed/comment/save',{method:'POST',body:JSON.stringify({post_id:Number(form.dataset.post),body:input.value})});input.value='';toast('Komentar dikirim');renderTimeline();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(form.id==='postForm'){
    event.preventDefault();
    if(form.dataset.submitting==='1')return;
    const fd=new FormData(form),obj=Object.fromEntries(fd.entries()),pairField=$('#postPair'),pairValue=pairField?.value||'',pair=pairValue.split('|').map(Number),bodyField=$('[name="body"]',form),fileField=$('#postFile'),fileObject=fileField?.files?.[0],btn=$('button[type="submit"],button:not([type])',form),cancelBtn=$('[data-close-modal]',form);
    const post={...obj,id:Number(obj.id||0),class_id:pair[0],subject_id:pair[1],body:String(obj.body||'').trim(),is_important:fd.has('is_important'),publish_at:obj.publish_at||''};
    if(!post.id)savePostDraft(post);
    if(!pairValue||!post.class_id||!post.subject_id){setPostStatus('Pilih Kelas & mata pelajaran sebelum menerbitkan.');pairField?.focus();return;}
    if(!post.body){setPostStatus('Isi kiriman wajib diisi sebelum menerbitkan.');bodyField?.focus();return;}
    if(fileObject?.size>UI_FILE_LIMIT){setPostStatus(`Lampiran ${fileObject.name} berukuran ${formatBytes(fileObject.size)} dan melebihi batas 8 MB. Pilih berkas yang lebih kecil.`);fileField?.focus();return;}
    const originalLabel=btn?.textContent||'Terbitkan';
    form.dataset.submitting='1';form.setAttribute('aria-busy','true');
    if(btn){btn.disabled=true;btn.textContent=fileObject?'Membaca lampiran...':'Mengirim...';}
    if(cancelBtn)cancelBtn.disabled=true;
    setPostStatus(fileObject?`Membaca ${fileObject.name} (${formatBytes(fileObject.size)})...`:'Mengirim kiriman. Jangan tutup halaman...','good');
    try{
      const file=await readUiFile(fileObject);
      if(btn)btn.textContent='Mengirim...';
      setPostStatus(fileObject?`Mengunggah ${fileObject.name}. Jangan tutup halaman...`:'Mengirim kiriman. Jangan tutup halaman...','good');
      await api('/api/feed/post/save',{method:'POST',body:JSON.stringify({...post,publish_at:post.publish_at?post.publish_at+':00':'',...file})});
      if(!post.id)clearPostDraft();
      toast('Kiriman disimpan');closeModal();renderTimeline();
    }catch(error){
      const sessionEnded=Number(error.code)===401,uncertain=!sessionEnded&&(!error.code||error.code==='NON_JSON_RESPONSE'||Number(error.code)>=500);
      const guidance=sessionEnded?'Silakan masuk kembali, lalu buka Linimasa Kelas dan pilih Buat Kiriman; draf akan dipulihkan.':uncertain?'Tutup kotak ini dan periksa linimasa. Jangan menerbitkan ulang sebelum memastikan kiriman belum muncul. Draf teks tetap tersimpan; lampiran perlu dipilih ulang.':'Periksa isian, lalu coba kembali. Draf teks tetap tersimpan; lampiran tetap dipilih selama kotak ini terbuka.';
      const errorTitle=uncertain?'Status kiriman belum pasti':'Kiriman belum tersimpan';
      setPostStatus(`${errorTitle}. ${error.message} ${guidance}`);
      if(sessionEnded){const box=$('#loginError');if(box){box.textContent=`${error.message} ${guidance}`;box.classList.remove('hidden')}}
      toast(errorTitle,`${error.message} ${guidance}`,'error');
      form.dataset.submitting='';form.removeAttribute('aria-busy');
      if(btn){btn.disabled=uncertain;btn.textContent=uncertain?'Periksa Linimasa':originalLabel;}
      if(cancelBtn)cancelBtn.disabled=false;
    }
    return;
  }
  if(form.id==='moduleForm'){event.preventDefault();const obj=Object.fromEntries(new FormData(form).entries()),pair=$('#modulePair').value.split('|').map(Number);submitForm(form,'/api/modules/save',()=>({...obj,id:Number(obj.id||0),class_id:pair[0],subject_id:pair[1],position:Number(obj.position)}),'Modul berhasil disimpan.');return;}
  if(form.id==='materialForm'){event.preventDefault();const fd=new FormData(form),obj=Object.fromEntries(fd.entries()),btn=$('button[type="submit"],button:not([type])',form);btn.disabled=true;try{const file=await readUiFile($('#materialFile').files[0]);await api('/api/materials/save',{method:'POST',body:JSON.stringify({...obj,id:Number(obj.id||0),module_id:Number(obj.module_id),position:Number(obj.position),publish_at:obj.publish_at?obj.publish_at+':00':'',...file})});toast('Materi disimpan');closeModal();renderMaterials();}catch(error){toast('Gagal',error.message,'error');btn.disabled=false}return;}
  if(form.id==='quizForm'){event.preventDefault();const fd=new FormData(form),obj=Object.fromEntries(fd.entries()),pair=$('#quizPair').value.split('|').map(Number);submitForm(form,'/api/quizzes/save',()=>({...obj,id:Number(obj.id||0),class_id:pair[0],subject_id:pair[1],duration_minutes:Number(obj.duration_minutes),max_attempts:Number(obj.max_attempts),shuffle_questions:fd.has('shuffle_questions'),shuffle_options:fd.has('shuffle_options'),show_result:fd.has('show_result'),open_at:obj.open_at+':00',close_at:obj.close_at+':00'}),'Kuis berhasil disimpan.');return;}
  if(form.id==='quizQuestionForm'){event.preventDefault();const obj=Object.fromEntries(new FormData(form).entries());try{await api('/api/quizzes/question/save',{method:'POST',body:JSON.stringify(questionPayload(obj))});toast('Soal disimpan');await openQuizQuestions(Number(obj.quiz_id));}catch(error){toast('Gagal',error.message,'error')}return;}
  if(form.id==='bankQuestionForm'){event.preventDefault();const obj=Object.fromEntries(new FormData(form).entries());try{await api('/api/question-bank/save',{method:'POST',body:JSON.stringify(questionPayload(obj))});toast('Bank soal diperbarui');closeModal();renderQuestionBank();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(form.id==='quizAttemptForm'){event.preventDefault();if(confirm('Kirim kuis sekarang? Jawaban tidak dapat diubah setelah dikirim.'))submitActiveQuiz(false);return;}
  if(form.id==='quizGradeForm'){event.preventDefault();const answers=$$('.essay-score',form).map(input=>({question_id:Number(input.dataset.question),score:Number(input.value),feedback:$(`.essay-feedback[data-question="${input.dataset.question}"]`,form)?.value||''})),feedback=new FormData(form).get('feedback')||'';try{await api('/api/quizzes/attempt/grade',{method:'POST',body:JSON.stringify({attempt_id:Number(new FormData(form).get('attempt_id')),answers,feedback})});toast('Penilaian kuis tersimpan');openQuizAttempts(state.quizAttempts.quiz.id);}catch(error){toast('Gagal',error.message,'error')}return;}
  if(form.id==='emailRequestForm'){event.preventDefault();const email=new FormData(form).get('email');try{await api('/api/profile/email/request',{method:'POST',body:JSON.stringify({email})});toast('Kode dikirim','Periksa kotak masuk dan spam.');closeModal();await loadData();state.page='profile';renderProfile();modalEmailCode();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(form.id==='emailCodeForm'){event.preventDefault();const code=new FormData(form).get('code');try{await api('/api/profile/email/confirm',{method:'POST',body:JSON.stringify({code})});toast('Email terbukti milik Anda','Sekarang menunggu persetujuan administrator.');closeModal();await loadData();state.page='profile';renderProfile();}catch(error){toast('Gagal',error.message,'error')}return;}
  if(form.id==='recoveryRequestForm'){event.preventDefault();const username=String(new FormData(form).get('username')||'').trim();try{const out=await api('/api/password/recovery/request',{method:'POST',body:JSON.stringify({username})});toast('Permintaan diproses',out.message);showRecoveryConfirm(username);}catch(error){toast('Gagal',error.message,'error')}return;}
  if(form.id==='recoveryConfirmForm'){event.preventDefault();const obj=Object.fromEntries(new FormData(form).entries());if(obj.new_password!==obj.confirm_password)return toast('Kata sandi belum sama','Ulangi kata sandi baru dengan tepat.','error');try{await api('/api/password/recovery/confirm',{method:'POST',body:JSON.stringify({username:obj.username,code:obj.code,new_password:obj.new_password})});closeModal();$('#loginUsername').value=obj.username;$('#loginPassword').value='';toast('Kata sandi dipulihkan','Silakan masuk dengan kata sandi baru.');}catch(error){toast('Gagal',error.message,'error')}return;}
});
